proof.raw:
First, we recall (this can be easily verified) that $\inf \{f(X): X \in \real^{n\times m}\}
>-\infty$ if and only if $Q \succeq 0$, and there exists at least one solution ${\bar X}$ such
that
\begin{equation}\label{s1}
 Q{\bar X}+ ab^T=0 \;
\Leftrightarrow\; {\bar X}^TQ +ba^T=0,
\end{equation}
i.e., the above is just $\nabla f (X)= 0$ and characterizes the minimizers of the convex
function $f(X)$. Using (\ref{s1}) it follows that $\inf_X f(X)=f({\bar X})=\trace (ba^T{\bar
X})$.
 Now, for any $\xi \in \mathbb{R}^n$, we have $f(\xi b^T)=\|b\|^2(\xi^TQ\xi + 2a^T\xi)$. Thus, likewise,
 $\inf\{f(\xi b^T): \xi \in \real^n\} >-\infty$ if and only if $Q \succeq 0$ and there exists ${\bar \xi}\in \real^n$ such
that \begin{equation}\label{s2} Q{\bar \xi} + a=0,\end{equation} and using (\ref{s2}) it
follows $\inf_\xi f(\xi b^T)=f({\bar \xi}b^T)=\|b\|^2a^T{\bar \xi}=\trace (ba^T{\bar
\xi}b^T)$. Now, using (\ref{s1})-(\ref{s2}), one obtains ${\bar X}^TQ=-ba^T$ and $Q({\bar X}-
{\bar \xi}b^T)=0$, and hence it follows that
\begin{eqnarray*}
f({\bar X})-f({\bar \xi})&=&\trace (ba^T({\bar X}- {\bar \xi}b^T))\\
                        &=&\trace (-{\bar X}^TQ({\bar X}- {\bar \xi}b^T)=0.
                        \end{eqnarray*}

example.raw:
\textbf{The Heavy Ball Method (HBM)}

\fbox{\parbox{14cm}{ {\bf Algorithm HBM} \medskip
\begin{enumerate}
\setcounter{enumi}{-1}

\item Input: $f\in C^{1,1}_L(\mathbb{R}^d)$, $x_0\in \mathbb{R}^d$,
\item $x_1 \leftarrow x_0 - \frac{\alpha}{L} f^\prime(x_0)$
\item For $i=1,\dots,N-1$ compute: $x_{i+1} = x_i - \frac{\alpha}{L} f^\prime(x_i) +\beta (x_i-x_{i-1})$
 \label{S:heavyballstep}
\end{enumerate}
}}
\medskip

Here the step sizes $\alpha$ and  $\beta$ are chosen such that $0 \leq \beta < 1$ and $0 < \alpha <
2(1+\beta)$, see \cite{polyak1964}.

By recursively eliminating the term $x_i-x_{i-1}$ in step 2 of HBM, we can rewrite this step
as
\[
    x_{i+1}= x_i - \frac{1}{L} \sum_{k=0}^{i} \alpha \beta^{i-k} f^\prime(x_k),\quad i=1,\dots,N-1.
\]
Therefore, the heavy ball method is a special case of Algorithm~\text{FO}\xspace with the choice
$$h^{(i+1)}_{k}= \alpha \beta^{i-k}, \quad  k=0, \ldots, i, \; i=0, \ldots N-1 .$$

\textbf{The fast gradient method (FGM)}

\fbox{\parbox{14cm}{ {\bf Algorithm FGM} \medskip
\begin{enumerate}
\setcounter{enumi}{-1}

\item Input: $f\in C^{1,1}_L(\mathbb{R}^d)$, $x_0\in \mathbb{R}^d$,
\item $y_1 \leftarrow x_0$, $t_1 \leftarrow 1$,
\item For $i=1,\dots,N$ compute:
\begin{enumerate}
    \item $x_i \leftarrow y_i -\frac{1}{L} f^\prime(y_i)$, \label{S:xdef}
    \item $t_{i+1} \leftarrow \frac{1+\sqrt{1+4 t_i^2}}{2}$,
    \item $y_{i+1} \leftarrow x_i + \frac{t_i-1}{t_{i+1}}(x_i-x_{i-1})$. \label{S:ydef}
\end{enumerate}
\end{enumerate}
}}

