As we shall show below, it turns out that this additional relaxation has no
damaging effects and produces the desired performance bound when $0< h\leq 1$.
\medskip

We are interested in deriving a  dual problem for \eqref{P:gpr} which is as simple as
possible, especially with respect to its dimension. As noted earlier, problem \eqref{P:gpr} is
a nonhomogeneous quadratic matrix program, and a dual problem for \eqref{P:gpr} could be
directly obtained by applying the results developed by Beck \cite{beck-qm06}. However, the
resulting obtained dual will involve an additional matrix variable $\Phi \in \mathbb{S}^d$,
where $d$ can be very large. Instead, here by exploiting the special structure of the second
set of nonhomogeneous inequalities given in \eqref{P:gpr}, we derive an alternative  dual
problem, but with only one additional variable $t \in \real$.

To establish our dual result, the next lemma shows that a dimension reduction is possible when
minimizing  a quadratic matrix function sharing the special form as the one that appears in
problem \eqref{P:gpr}.

\begin{lemma}\label{L:quadlemma}
Let $f(X)=\trace (X^T Q X + 2 ba^T X)$ be a quadratic function, where $X\in
\mathbb{R}^{n\times m}$, $Q\in \mathbb{S}^n$, $a\in \mathbb{R}^n$ and $0\neq b\in
\mathbb{R}^m$. Then
\[
    \inf_{X\in \mathbb{R}^{n\times m}} f(X) = \inf_{\xi\in \mathbb{R}^n} f(\xi b^T).
\]
\end{lemma}
\begin{proof}
First, we recall (this can be easily verified) that $\inf \{f(X): X \in \real^{n\times m}\}
>-\infty$ if and only if $Q \succeq 0$, and there exists at least one solution ${\bar X}$ such
that
\begin{equation}\label{s1}
 Q{\bar X}+ ab^T=0 \;
\Leftrightarrow\; {\bar X}^TQ +ba^T=0,
\end{equation}
i.e., the above is just $\nabla f (X)= 0$ and characterizes the minimizers of the convex
function $f(X)$. Using (\ref{s1}) it follows that $\inf_X f(X)=f({\bar X})=\trace (ba^T{\bar
X})$.
 Now, for any $\xi \in \mathbb{R}^n$, we have $f(\xi b^T)=\|b\|^2(\xi^TQ\xi + 2a^T\xi)$. Thus, likewise,
 $\inf\{f(\xi b^T): \xi \in \real^n\} >-\infty$ if and only if $Q \succeq 0$ and there exists ${\bar \xi}\in \real^n$ such
that \begin{equation}\label{s2} Q{\bar \xi} + a=0,\end{equation} and using (\ref{s2}) it
follows $\inf_\xi f(\xi b^T)=f({\bar \xi}b^T)=\|b\|^2a^T{\bar \xi}=\trace (ba^T{\bar
\xi}b^T)$. Now, using (\ref{s1})-(\ref{s2}), one obtains ${\bar X}^TQ=-ba^T$ and $Q({\bar X}-
{\bar \xi}b^T)=0$, and hence it follows that
\begin{eqnarray*}
f({\bar X})-f({\bar \xi})&=&\trace (ba^T({\bar X}- {\bar \xi}b^T))\\
                        &=&\trace (-{\bar X}^TQ({\bar X}- {\bar \xi}b^T)=0.
                        \end{eqnarray*}
\end{proof}

Equipped with Lemma \ref{L:quadlemma},  we now derive  a Lagrangian dual for problem
\eqref{P:gpr}.

\begin{lemma}\label{lem:dual} Consider problem \eqref{P:gpr} for any fixed $h\in \real$ and  $L,R >0$.
A Lagrangian dual of \eqref{P:gpr} is given by the following convex program:
\begin{align*}
    \begin{aligned}
        \min_{\lambda \in \real^N, t \in \real}\{\frac{1}{2} LR^2 t:\; \lambda \in \Lambda, \; S(\lambda, t) \succeq 0 \},
    \end{aligned}
    \tag{DG$^\prime$}\label{P:dualgpr}
\end{align*}
where $\Lambda:=\{\lambda \in \real^N:\; \lambda_{i+1}-\lambda_i \geq 0, \quad
i=1,\dots,N-1,\; 1-\lambda_N \geq 0,\; \lambda_i \geq 0,\quad i=1,\dots,N\}$,
the matrix
$S(\cdot,\cdot)\in \mathbb{S}^{N+2}$ is given by \[
    S(\lambda,t)=\begin{pmatrix}
                (1-h)S_0 + h S_1    & q \\
                q^T     & t
        \end{pmatrix},
\]
with $q=(\lambda_1,\lambda_2-\lambda_1,\dots,\lambda_N-\lambda_{N-1},1-\lambda_N)^T$ and where
the matrices $S_0, S_1\in \mathbb{S}^{N+1}$ are  defined by: {\small
\begin{equation}\label{b0matrix}
    S_0=
    \begin{pmatrix}
        2 \lambda_1     & -\lambda_1            \\
        -\lambda_1          & 2 \lambda_2   & -\lambda_2                \\
            &       -\lambda_2          & 2 \lambda_3   & -\lambda_3                \\
                                    &        & \ddots        &\ddots &   \ddots\\
                                            & &                 &       -\lambda_{N-1}  & 2 \lambda_N & -\lambda_N \\
                                            & &                 &        &  -\lambda_N  & 1\\
    \end{pmatrix}
\end{equation}

{\small {\begin{equation}\label{b1matrix}
    S_1=
        \begin{pmatrix}
        2 \lambda_1         & \lambda_2-\lambda_1           &\dots          &\lambda_N-\lambda_{N-1}    &1-\lambda_N  \\
        \lambda_2-\lambda_1         & 2 \lambda_2                   &           &\lambda_N-\lambda_{N-1}    &1-\lambda_N \\

        \vdots & & \ddots & &\vdots \\
        \lambda_N-\lambda_{N-1}     & \lambda_N-\lambda_{N-1}   &       & 2\lambda_N    & 1-\lambda_N  \\
        1-\lambda_N         & 1-\lambda_N       & \dots         & 1-\lambda_N   & 1 \\
    \end{pmatrix}
    .
\end{equation}}}
\end{lemma}
\begin{proof}
For convenience,  we recast \eqref{P:gpr} as a minimization problem, and we also omit the
fixed term $LR^2$ from the objective. That is, we consider the equivalent problem \eqref{P:agpr}
defined by
\begin{align*}
    \begin{aligned}
    \min_{G\in \mathbb{R}^{(N+1)\times d},\delta \in\mathbb{R}^{N+1}}\ &  -\delta_N \\
    \text{s.t. }
                        & \trace (G^T A_{i-1,i} G) \leq \delta_{i-1} - \delta_i,\quad    i=1,\dots,N, \\
                        & \trace(G^T D_i G+ \nu u_i^T G ) \leq - \delta_i,\quad     i=0,\dots,N.
    \end{aligned}
    \tag{G$^{\prime\prime}$}\label{P:agpr}
\end{align*}

Attaching the dual multipliers $\lambda=(\lambda_1,\dots,\lambda_N) \in \real^N_{+}$ and
$\tau:=(\tau_0, \ldots ,\tau_N)^T \in \real^{N+1}_{+}$ to the first and second set of
inequalities respectively, and using the notation $\delta=(\delta_0, \ldots ,\delta_N)$, we
get that the Lagrangian of this problem is given as a sum of two separable functions in the
variables $(\delta, G)$:
\begin{eqnarray*}
    L(G,\delta, \lambda, \tau)&=&


         -\delta_N+\sum_{i=1}^{N} \lambda_i(\delta_i - \delta_{i-1}) + \sum_{i=0}^N \tau_i \delta_i \\
         & &+ \sum_{i=1}^{N} \lambda_i \trace(G^T A_{i-1,i} G)+ \sum_{i=0}^N \tau_i
        \left( \trace(G^T D_i G+ \nu u_i^T G) \right)\\
        & \equiv & L_1(\delta, \lambda, \tau)+ L_2(G,\lambda, \tau).
\end{eqnarray*}

