with
\begin{align}
    h^{(i+1)}_k = \begin{cases}
        \frac{t_{i}-1}{t_{i+1}}h^{(i)}_k    & k+2\leq i, \\
        \frac{t_{i}-1}{t_{i+1}}(h^{(i)}_{i-1}-1)    & k = i-1, \\
        1+\frac{t_{i}-1}{t_{i+1}}   & k = i
    \end{cases} \qquad (i=1,\dots,N-1, \ k=1,\dots,i). \label{E:nesterovsteps}
\end{align}
and
\begin{align*}
    t_i =
        \begin{cases}
            1       & i=1 \\
            \frac{1+\sqrt{1+4 t_{i-1}^2}}{2} & i>1.
        \end{cases}
\end{align*}

\begin{proposition}
The points $y_1,\dots,y_N,x_N$ generated by Algorithm~\text{FGM$^\prime$}\xspace are identical to the
respective points generated by Algorithm~\text{FGM}\xspace.
\end{proposition}
\begin{proof}
We will show by induction that the sequence $y_i$ generated by Algorithm~\text{FGM$^\prime$}\xspace is
identical to the sequence $y_i$ generated by Algorithm~\text{FGM}\xspace, and that the value of
$x_N$ generated by Algorithm~\text{FGM$^\prime$}\xspace is equal to the value of $x_N$ generated by
Algorithm~\text{FGM}\xspace.

First note that the sequence $t_i$ is defined by the two algorithms in the same way. Now let
$\{x_i$, $y_i\}$ be the sequences generated by \text{FGM}\xspace and denote by $\{y_i^\prime\}$,
$x_N^\prime$ the sequence generated by \text{FGM$^\prime$}\xspace. Obviously, $y^\prime_1 = y_1$ and since
$t_1=1$ we get using the relations \ref{E:nesterovsteps}:
\begin{align*}
    y_2^\prime &= y_1^\prime - \frac{1}{L} h^{(2)}_1 f^\prime(y_1^\prime) = y_1 - \frac{1}{L} \left(1+\frac{t_{1}-1}{t_2} \right) f^\prime(y_1) = y_1 - \frac{1}{L} f^\prime(y_1)= x_1 = y_2.
\end{align*}
Assuming $y_i^\prime = y_i$ for $i = 1,\dots,n$, we then have
\begin{align*}
    y_{n+1}^\prime &= y_n^\prime - \frac{1}{L} h^{(n+1)}_n f^\prime(y_n^\prime) - \frac{1}{L} h^{(n+1)}_{n-1} f^\prime(y_{n-1}^\prime) - \frac{1}{L} \sum_{k=1}^{n-2} h^{(n+1)}_k f^\prime(y_k^\prime) \\
        &= y_n - \frac{1}{L} (1+\frac{t_n-1}{t_{n+1}}) f^\prime(y_n) - \frac{1}{L} \frac{t_n-1}{t_{n+1}}(h^{(n)}_{n-1}-1) f^\prime(y_{n-1}) - \frac{1}{L} \sum_{k=1}^{n-2} \frac{t_n-1}{t_{n+1}}h^{(n)}_k f^\prime(y_k^\prime) \\
        &= y_n - \frac{1}{L} f^\prime(y_n) +\frac{t_n-1}{t_{n+1}} \left( -\frac{1}{L}  f^\prime(y_n) + \frac{1}{L} f^\prime(y_{n-1}) - \frac{1}{L} \sum_{k=1}^{n-1} h^{(n)}_k f^\prime(y_k^\prime)\right) \\
        &= x_n +\frac{t_n-1}{t_{n+1}} \left( -\frac{1}{L}  f^\prime(y_n) + \frac{1}{L} f^\prime(y_{n-1}) +y_n^\prime-y_{n-1}^\prime\right) \\
        &= x_n +\frac{t_n-1}{t_{n+1}} (x_n-x_{n-1}) \\
        &= y_{n+1}.
\end{align*}
Finally,
\[
    x_N^\prime = y_N^\prime -\frac{1}{L} f^\prime(y_N^\prime) = y_N -\frac{1}{L} f^\prime(y_N) = x_N.
\]

\end{proof}

\xspace}\label{S:optalg}




We now consider the problem of finding the ``best" performing algorithm of the form \text{FO}\xspace
with respect to the new bounds. Namely, we consider the problem of minimizing
$\val\eqref{P:fopr}$, the optimal value of \eqref{P:fopr},
with respect to the step sizes $h:=(h^{(i)}_k)_{0\leq k<i \leq N}$
defining the algorithm \text{FO}\xspace, and which are now considered as unknown variables in
\text{FO}\xspace.



We denote by  $\tilde{A}_{i,j}(h)$ and $\tilde{D}_i(h)$, the matrices given in
\eqref{E:defmatrices},  which are functions of the algorithm step sizes $h$. The resulting
bound derived in Proposition \ref{numb} is thus a function of $h$, and the problem of
minimizing $\val \eqref{P:foprd}$ with respect to the step sizes $h$ thus consists of solving
the following bilinear problem: {\small
\begin{align*}
    \begin{aligned}
    \min_{h,\lambda, \tau,t}\ \left \{ \frac{1}{2} t :
           \begin{pmatrix}
                \sum_{i=1}^N \lambda_i  \tilde{A}_{i-1,i}(h)  + \sum_{i=0}^N \tau_i  \tilde{D}_i(h)  &\frac{1}{2} \tau \\
                \frac{1}{2} \tau^T      & \frac{1}{2} t
        \end{pmatrix} \succeq 0,
         (\lambda, \tau) \in \tilde{\Lambda} \right\},
    \end{aligned}
    \tag{BIL}\label{P:pblin}
\end{align*}
} with $\tilde{\Lambda}$ defined as in \eqref{E:duallinearconstraints}.

Note that
the feasibility of \eqref{P:pblin} follows from
the proof of Theorem~\ref{T:gradLowBound}, where an explicit feasible point is given to \eqref{P:dualgpr},
which is a special instance of \eqref{P:pblin} when the steps $(h^{(i)}_k)$ are chosen as in the gradient method.

From the definition of the matrices $\tilde{A}_{i,j}(h)$ and $\tilde{D}_i(h)$, we get
\begin{align*}
    \sum_{i=1}^N \lambda_i  \tilde{A}_{i-1,i}(h)  + \sum_{i=0}^N \tau_i  \tilde{D}_i(h)
    &= \frac{1}{2}\sum_{i=1}^{N} \lambda_i (u_{i-1}-u_i)(u_{i-1}-u_i)^T +\frac{1}{2}\sum_{i=0}^{N}
    \tau_i u_i u_i^T  \\&\quad+  \frac{1}{2}\sum_{i=1}^{N} \sum_{k=0}^{i-1}
    \left( \lambda_i h_k^{(i)}+\tau_i \sum_{t=k+1}^{i} h_k^{(t)}\right) (u_i u_k^T + u_k
    u_i^T).
\end{align*}
Introducing the new variables:
\begin{equation}\label{E:definex}
    r_{i,k}=  \lambda_i h_k^{(i)}+\tau_i \sum_{t=k+1}^{i} h_k^{(t)}, \quad i=1,\dots,N,\ k=0,\dots,i-1
\end{equation}
and denoting $r=(r_{i,k})_{0\leq k<i \leq N}$, we obtain the following \emph{linear} SDP
relaxation of \eqref{P:pblin}:
\begin{align*}
    \begin{aligned}
    \min_{r,\lambda, \tau,t}\ \left\{ \frac{1}{2} t :
            \begin{pmatrix}
                S(r,\lambda,\tau)  &\frac{1}{2} \tau \\
                \frac{1}{2} \tau^T      & \frac{1}{2} t
        \end{pmatrix} \succeq 0, \
        (\lambda, \tau) \in \tilde{\Lambda} \right\},
    \end{aligned}
    \tag{LIN}\label{P:plin}
\end{align*}
where
\begin{align*}
     S(r,\lambda,\tau)
    &= \frac{1}{2}\sum_{i=1}^{N} \lambda_i (u_{i-1}-u_i)(u_{i-1}-u_i)^T +\frac{1}{2}\sum_{i=0}^{N} \tau_i u_i u_i^T  +  \frac{1}{2}\sum_{i=1}^{N} \sum_{k=0}^{i-1} r_{i,k} (u_i u_k^T + u_k u_i^T).
\end{align*}

This convex SDP can now be efficiently solved by numerical methods. As the following theorem
shows, its solution can be used to construct a solution for \eqref{P:pblin} with optimal step
sizes $h$.
\begin{theorem}
Suppose $(r^\ast,\lambda^\ast,\tau^\ast,t^\ast)$ is an optimal solution for (LIN),
then $(h,\lambda^\ast,\tau^\ast,t^\ast)$ is an optimal solution for \eqref{P:pblin}, where
$h=(h_k^{(i)})_{0\leq k<i \leq N}$ is defined by the following recursive rule
\begin{equation}\label{E:solvebil}
    h_k^{(i)} = \begin{cases}
            \frac{\tau_i^\ast \sum_{t=k+1}^{i-1} h_k^{(t)} -r_{i,k}^\ast }{\lambda_{i}^\ast} & \lambda_i^\ast \neq 0\\
            0   & \lambda_i^\ast = 0
        \end{cases},  \quad i=1,\dots,N,\ k=0,\dots,i-1.
\end{equation}
\end{theorem}
\begin{proof}
As (LIN) is a relaxation of \eqref{P:pblin}, it is enough to show that \eqref{P:pblin} can achieve the same
objective value. Let $(r^\ast,\lambda^\ast,\tau^\ast,t^\ast)$ be an optimal solution
for (LIN). If $\lambda_i^\ast \neq 0$ for all $1\leq i \leq N$, then~\eqref{E:solvebil}
satisfies all the equations in \eqref{E:definex} and therefore
$(h,\lambda^\ast,\tau^\ast,t^\ast)$ is feasible for \eqref{P:pblin}.

Suppose $\lambda^\ast_m=0$ for some $1\leq m \leq N$ and that $m$ is the maximal index with
this property. Then by the equality and non-negativity constraints in (LIN), we get that
$\lambda^\ast_1=\lambda^\ast_2=\dots=\lambda^\ast_m=0$ and
$\tau^\ast_0=\tau^\ast_1=\dots=\tau^\ast_{m-1}=0$.
Let $S:=S(r,\lambda^\ast,\tau^\ast)$, then by the positive semidefinite constraint in (LIN), we have $S \succeq 0$.
From the linear equalities connecting $\lambda$ and $\tau$ it follows that
\[
    S_{i,i}=\begin{cases}
            \frac{1}{2} (\lambda_1^\ast+\tau_0^\ast) = \lambda_1^\ast, &\quad i=1 \\
            \frac{1}{2} (\lambda_i^\ast+\lambda_{i-1}^\ast+\tau_{i-1}^\ast) = \lambda_i^\ast, &\quad i=2,\dots,N
        \end{cases},
\]
and we get that $S_{1,1}=\dots=S_{m,m}=0$. By the properties of positive semidefinite matrices we now get that $r_{i,k}^\ast=0$ for $i=1,\dots,m$ and $k=0,\dots,i-1$,
hence the set of equations \eqref{E:definex} with the chosen values of $h_k^{(i)}$ is consistent.
\end{proof}

